//! ↩️ reorder-meshs leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfMesh;
use crate::artifacts::gltf::schema::mutations::reorder_meshs::mutation::{validate, GltfReorderMeshsPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{meshes_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-meshs.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderMeshsInverseOperation { Insert { position: usize, item: GltfMesh }, Delete { index: usize, removed: GltfMesh }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderMeshsInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderMeshsPayload, pub operation: GltfReorderMeshsInverseOperation }
async fn operation(payload: &GltfReorderMeshsPayload, base: &GltfSnapshot) -> GltfReorderMeshsInverseOperation { GltfReorderMeshsInverseOperation::Reorder { order: (0..payload.order.len()).map(|index| payload.order.iter().position(|value| *value == index).unwrap()).collect() } }
async fn touched_paths(payload: &GltfReorderMeshsPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/meshes/{}", index)).chain(std::iter::empty()).collect() }
pub async fn validate_inverse(inverse: &GltfReorderMeshsInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub async fn apply_inverse(inverse: &GltfReorderMeshsInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfReorderMeshsInverseOperation::Insert { position, .. } if *position > after.document.meshes.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/meshes", "position must be within the collection")), GltfReorderMeshsInverseOperation::Delete { index, .. } if *index >= after.document.meshes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/meshes", "index must address an item")), GltfReorderMeshsInverseOperation::Move { index, position } if *index >= after.document.meshes.len() || *position >= after.document.meshes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/meshes", "indices must address items")), GltfReorderMeshsInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.meshes.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.meshes.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/meshes", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfReorderMeshsInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Meshes, &Change::Insert(*position))?; next.document.meshes.insert(*position, item.clone());  }, GltfReorderMeshsInverseOperation::Delete { index, .. } => { meshes_op(&mut next, GltfTopLevelFamily::Meshes, *index, None, None)?;  }, GltfReorderMeshsInverseOperation::Move { index, position } => { meshes_op(&mut next, GltfTopLevelFamily::Meshes, *index, Some(*position), None)?;  }, GltfReorderMeshsInverseOperation::Reorder { order } => { meshes_op(&mut next, GltfTopLevelFamily::Meshes, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(inverse: &GltfReorderMeshsInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub async fn derive(payload: &GltfReorderMeshsPayload, base: &GltfSnapshot) -> Result<GltfReorderMeshsInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderMeshsInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
